class CrescendoAttackVDB(CrescendoAttack):
    """Truncate last target text in adversarial prompts (draft max_model_len=8192)."""

    def _build_adversarial_prompt(
        self,
        *,
        context: CrescendoAttackContext,
        refused_text: str,
    ) -> str:
        if refused_text:
            refused_text = truncate_for_draft(refused_text)
        prompt = super()._build_adversarial_prompt(
            context=context,
            refused_text=refused_text,
        )
